function showPost(p){const dialog=document.querySelector('#post-dialog');d3.select('#dialog-image').html('');if(p.image)d3.select('#dialog-image').append('img').attr('src',p.image).attr('alt',p.title);else d3.select('#dialog-image').append('p').text('No standalone visual was found.');let c=d3.select('#dialog-copy');c.html('');c.append('div').attr('class','eyebrow').text(`POST ${String(p.index).padStart(3,'0')} · ${p.date}`);c.append('h2').text(p.title);c.append('p').text(`${p.topic} · ${p.type}`);c.append('p').text(`Package: ${fmt(p.reactions)} reactions / ${fmt(p.comments)} comments. Browser: ${fmt(p.liveReactions)} reactions / ${fmt(p.liveComments)} comments.`);c.append('p').attr('class','caption').text(p.caption||p.sharedText||'No author caption recovered.');let links=c.append('div').attr('class','sourcebuttons');if(p.source)links.append('a').attr('class','button').attr('href',p.source).attr('target','_blank').attr('rel','noopener').text('Open source');if(p.image)links.append('a').attr('class','button').attr('href',p.image).attr('target','_blank').text('Full image');if(!dialog.open)dialog.showModal();}
