function saveBlob(blob,name){let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function exportFigure(svg,name,kind){const clean=svg.cloneNode(true);clean.removeAttribute('style');clean.querySelectorAll('.is-muted,.is-hovered,.is-selected').forEach(m=>m.classList.remove('is-muted','is-hovered','is-selected'));await Promise.all([...clean.querySelectorAll('image')].map(async image=>{const href=image.getAttribute('href')||image.getAttribute('data-src');if(href&&!href.startsWith('data:')){const response=await fetch(href);if(!response.ok)throw new Error('Image export failed');const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});image.setAttribute('href',data)}}));const xml=new XMLSerializer().serializeToString(clean);if(kind==='svg')return saveBlob(new Blob([xml],{type:'image/svg+xml'}),name+'.svg');const img=new Image(),url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));img.onload=()=>{let cv=document.createElement('canvas');cv.width=svg.viewBox.baseVal.width*3;cv.height=svg.viewBox.baseVal.height*3;cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);cv.toBlob(b=>saveBlob(b,name+'.png'),'image/png');URL.revokeObjectURL(url)};img.src=url;}
