function tiles(v,rows,order,groupKey){let data=[...rows];data.sort(order==='comments'?(a,b)=>(b.comments??-1)-(a.comments??-1):order==='reactions'?(a,b)=>(b.reactions??-1)-(a.reactions??-1):order==='rank'?(a,b)=>(a.rank??9999)-(b.rank??9999):order==='old'?(a,b)=>a.date.localeCompare(b.date):(a,b)=>b.date.localeCompare(a.date));const stateKey=order+'|'+groupKey+'|'+data.map(p=>p.id).join(',');if(v.tileKey!==stateKey){v.tileKey=stateKey;v.tileLimit=48;v.compareIds=[]}const visible=data.slice(0,v.tileLimit);const groups=groupKey?d3.groups(visible,p=>p[groupKey]):[['Selected posts',visible]];groups.forEach(([name,posts])=>{v.chart.append('h3').text(`${name} · ${posts.length} shown`);const grid=v.chart.append('div').attr('class','explore-mosaic');posts.forEach(p=>{const b=grid.append('button').attr('aria-label',`${p.title}, ${p.date}, open post`).on('click',()=>{if(v.imageMode?.()==='compare'){v.compareIds||=[];if(v.compareIds.includes(p.id))v.compareIds=v.compareIds.filter(id=>id!==p.id);else{if(v.compareIds.length===2)v.compareIds=[];v.compareIds.push(p.id)}v.selection.html('');v.selection.append('span').text(v.compareIds.length===1?'One visual selected. Choose a second to compare.':'Choose two visuals to compare.');if(v.compareIds.length===2)compareVisuals(v.compareIds.map(id=>index.get(id)));}else showPost(p)});if(p.embedded)b.append('img').attr('src',p.embedded).attr('loading','lazy').attr('alt',p.title);else b.append('span').text('No visual');b.append('small').text(`${p.date} · ${order==='comments'?fmt(p.comments)+' comments':order==='reactions'?fmt(p.reactions)+' reactions':'#'+p.index}`)})});if(visible.length<data.length)v.chart.append('button').attr('class','more-visuals').text(`Show ${Math.min(48,data.length-visible.length)} more visuals`).on('click',()=>{v.tileLimit+=48;v.draw()});v.insight.text(`${visible.length} of ${data.length} matching posts shown. ${v.imageMode?.()==='compare'?'Choose two images to compare their artwork, captions and response.':'Select an image to read the post.'} Image proportions are preserved; ordering uses package counters.`);}
